/* r15: yeni Mega Evolution setleri pokemontcg.io'da yok — scrydex CDN'inde.
   (Ascended Heroes=me2pt5, Perfect Order=me3, Chaos Rising=me4) */
function kartGorsel(sid, num, boy){
  if(sid === 'me2pt5' || sid === 'me3' || sid === 'me4')
    return `https://images.scrydex.com/pokemon/${sid}-${num}/${boy || 'small'}`;
  if(sid === 'cel25c') return `https://images.pokemontcg.io/${sid}/${num}_A.png`;
  return `https://images.pokemontcg.io/${sid}/${num}.png`;
}

function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function pokeSlug(name){
  let n=String(name).toLowerCase();
  const pre=['dark ','light ','shining ','team rocket\'s ','team aqua\'s ','team magma\'s ','rocket\'s ','brock\'s ','misty\'s ','lt. surge\'s ','erika\'s ','sabrina\'s ','koga\'s ','blaine\'s ','giovanni\'s ','m ','mega ','radiant ','shadow '];
  const suf=[' ex',' gx',' v',' vmax',' vstar',' v-union',' break',' prime',' legend',' star'];
  for(const p of pre) if(n.startsWith(p)) n=n.slice(p.length);
  for(const s of suf) if(n.endsWith(s)) n=n.slice(0,-s.length);
  n=n.replace(/\s*\(.*?\)/g,'').trim();
  const tr={'ç':'c','ğ':'g','ı':'i','ö':'o','ü':'u','ş':'s','&':'and',"'":'','’':'','.':'',' ':'-'};
  for(const k in tr) n=n.split(k).join(tr[k]);
  return n.replace(/[^a-z0-9-]+/g,'').replace(/^-+|-+$/g,'');
}
function fmtTL(t){return Math.round(t).toLocaleString('tr-TR');} /* fiyatlar artık dogrudan TL (PriceCharting x guncel kur, 2026-07) */

